@DataClassName('StudentRow')
class Students extends Table {
  TextColumn get nim => text()();
  TextColumn get name => text()();
  IntColumn get sksSemester => integer()();
  IntColumn get sksTotal => integer()();
  RealColumn get ipSemester => real()();
  RealColumn get ipCumulative => real()();
  IntColumn get lastFetched => integer()();

  @override
  Set<Column> get primaryKey => {nim};
}

@DataClassName('CourseRow')
class Courses extends Table {
  /// Server id (not auto-generated).
  IntColumn get id => integer()();
  TextColumn get name => text()();
  TextColumn get code => text()();
  IntColumn get colorIndex => integer()();
  IntColumn get grade => integer()();
  TextColumn get letter => text()();
  IntColumn get taskScore => integer()();
  IntColumn get attendScore => integer()();
  IntColumn get utsScore => integer()();
  IntColumn get uasScore => integer()();
  IntColumn get attendPercent => integer()();
  IntColumn get attendCount => integer()();
  IntColumn get permitCount => integer()();
  IntColumn get sickCount => integer()();
  IntColumn get alphaCount => integer()();
  IntColumn get lastFetched => integer()();

  @override
  Set<Column> get primaryKey => {id};
}

@DataClassName('AssessmentRow')
class Assessments extends Table {
  IntColumn get id => integer().autoIncrement()();
  IntColumn get courseId =>
      integer().references(Courses, #id, onDelete: KeyAction.cascade)();
  TextColumn get title => text()();

  /// AssessmentStatus.name
  TextColumn get status => text()();
  IntColumn get score => integer().nullable()();

  /// Keeps the server's order.
  IntColumn get position => integer()();
}

@DataClassName('AttendanceRow')
